/*
 * NTSC palette generated by simulating the 2C02 composite signal
 * (square-wave chroma + luma levels, with colour emphasis attenuation)
 * and decoding it through a YIQ demodulator. Produces all 512 entries
 * (64 colours x 8 emphasis combinations).
 */
#include "nes.h"
#include <math.h>

static float ntsc_signal(int pixel, int phase) {
    static const float levels[8] = { .350f, .518f, .962f, 1.550f, 1.094f, 1.506f, 1.962f, 1.962f };
    static const float attenuation = .746f;
    int color = pixel & 0x0F, level = (pixel >> 4) & 3, emphasis = pixel >> 6;
    if (color > 13) level = 1;
    float low = levels[level], high = levels[4 + level];
    if (color == 0) low = high;
    if (color > 12) high = low;
#define IN_PHASE(c) (((c) + phase) % 12 < 6)
    float signal = IN_PHASE(color) ? high : low;
    if (((emphasis & 1) && IN_PHASE(0)) || ((emphasis & 2) && IN_PHASE(4)) || ((emphasis & 4) && IN_PHASE(8)))
        signal *= attenuation;
#undef IN_PHASE
    return signal;
}

static int clamp255(double v) {
    if (v <= 0) return 0;
    v = pow(v, 2.2 / 2.2);
    int r = (int)(v * 255.0 + 0.5);
    return r > 255 ? 255 : r;
}

void palette_generate(uint32_t *out) { palette_generate_ex(out, 0, 1, 0, 1); }

/* hue_deg: hue rotation in degrees; sat: saturation multiplier;
 * bri: brightness offset (-1..1); con: contrast multiplier */
void palette_generate_ex(uint32_t *out, double hue_deg, double sat_mul, double bri, double con) {
    const double black = .518, white = 1.962;
    const double hue = 3.8 + hue_deg / 30.0, sat = 1.2 * sat_mul;
    for (int pix = 0; pix < 512; pix++) {
        double y = 0, i = 0, q = 0;
        for (int p = 0; p < 12; p++) {
            double s = (ntsc_signal(pix, p) - black) / (white - black);
            y += s;
            i += s * cos(M_PI * (p + hue) / 6.0);
            q += s * sin(M_PI * (p + hue) / 6.0);
        }
        y /= 12; i = i / 12 * sat; q = q / 12 * sat;
        double r = y + 0.946882 * i + 0.623557 * q;
        double g = y - 0.274788 * i - 0.635691 * q;
        double b = y - 1.108545 * i + 1.709007 * q;
        r = (r - 0.5) * con + 0.5 + bri; g = (g - 0.5) * con + 0.5 + bri; b = (b - 0.5) * con + 0.5 + bri;
        out[pix] = 0xFF000000u | (uint32_t)clamp255(r) << 16 | (uint32_t)clamp255(g) << 8 | (uint32_t)clamp255(b);
    }
}
